export type MoniqLanguage = "ru" | "en" | "lv";

export function parseMoniqLanguage(value?: string): MoniqLanguage {
  return value === "en" || value === "lv" ? value : "ru";
}

export function moniqI18n(language: MoniqLanguage) {
  const locale = { ru: "ru-RU", en: "en-GB", lv: "lv-LV" }[language];
  function msg(text: string, values?: Record<string, string | number>) {
    const entry = Object.hasOwn(messages, text) ? messages[text] : undefined;
    const translated = (language === "en" ? entry?.[0] : language === "lv" ? entry?.[1] : undefined) ?? text;
    return values ? translated.replace(/\{(\w+)\}/g, (match, key) => String(values[key] ?? match)) : translated;
  }
  function errorMessage(error: unknown, fallback: string) {
    return typeof error === "string" && error.trim() ? msg(error) : fallback;
  }

  return { language, locale, msg, errorMessage };
}
